mapper.select:
select A.* from ( SELECT @ROWNUM := @ROWNUM + 1 as ROWNUM, TB.* from ( select mem_seq_no as memSeqNo , mem_id as memId , mem_name as memName , mem_pwd as memPwd , mem_birth as memBirth , mem_phone as memPhone , mem_email as memEmail , mem_zipcode as memZipcode , mem_addr_master as memAddrMaster , mem_addr_detail as memAddrDetail , mem_type as memType FROM tb_member where 1=1
and mem_id = #{searchWord}
and mem_name LIKE CONCAT('%', #{searchWord}, '%')
order by mem_seq_no DESC ) TB, ( select @ROWNUM := 0 ) R ) A where A.ROWNUM between #{startRow} and #{endRow}

select count(*) from tb_member where 1=1
and mem_id = #{searchWord}
and mem_name LIKE CONCAT('%', #{searchWord}, '%')

select mem_seq_no as memSeqNo , mem_id as memId , mem_name as memName , mem_pwd as memPwd , mem_birth as memBirth , mem_phone as memPhone , mem_email as memEmail , mem_zipcode as memZipcode , mem_addr_master as memAddrMaster , mem_addr_detail as memAddrDetail , mem_type as memType from tb_member where 1=1
and mem_seq_no = #{seqNo}
and mem_id = #{memId}

mapper.insert:
insert into tb_member (
	mem_id
	, mem_name
	, mem_pwd
	, mem_birth
	, mem_phone
	, mem_email
	, mem_zipcode
	, mem_addr_master
	, mem_addr_detail 
) values (
      #{memId}
	, #{memName}
	, #{memPwd}
	, #{memBirth}
	, #{memPhone}
	, #{memEmail}
	, #{memZipcode}
	, #{memAddrMaster}
	, #{memAddrDetail}
)

mapper.update:
update tb_member
set
	mem_pwd 				= #{memPwd}
	, mem_phone			 = #{memPhone}
	, mem_email				 = #{memEmail}
	, mem_birth 				= #{memBirth}
	, mem_zipcode 			= #{memZipcode}
	, mem_addr_master 	= #{memAddrMaster}
	, mem_addr_detail 		= #{memAddrDetail}
where mem_seq_no 		= #{memSeqNo}
